def solution(input_text):
    """
    Sprague-Grundy game solver.
    """
    lines = input_text.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    memo = {}

    def compute_grundy(x):
        if x == 0:
            return 0
        if x == 1:
            return 1
        if x <= 3:
            return x
        if x in memo:
            return memo[x]

        reachable = {compute_grundy(x - 1)}

        if x % 2 == 0:
            half = x // 2
            if k % 2 == 0:
                reachable.add(0)
            else:
                reachable.add(compute_grundy(half))

        mex = 0
        while mex in reachable:
            mex += 1

        memo[x] = mex
        return mex

    xor_sum = sum(compute_grundy(pile) for pile in a)
    return "Kevin\n" if xor_sum != 0 else "Nicky\n"

