                            if grid[i + di][j + dj] != '0' and grid[i + di][j + dj] == grid[i][j]:
                                return False
        return True

    # First check if given colors already conflict
    if not check_initial():
        return '0'

    # Greedily fill missing cells
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '0':
                used = set()
                for ni, nj in get_neighbors(i, j):
