def mat_mul(A, B, mod):
    n = len(A)
    m = len(B[0])
    result = [[0] * m for _ in range(n)]
    for i in range(n):
        for j in range(m):
            for k in range(len(B)):
                result[i][j] = (result[i][j] + A[i][k] * B[k][j]) % mod
    return result

def mat_pow(A, p, mod):
    n = len(A)
    result = [[0] * n for _ in range(n)]
    for i in range(n):
        result[i][i] = 1
    base = [row[:] for row in A]
    while p > 0:
        if p % 2 == 1:
            result = mat_mul(result, base, mod)
        base = mat_mul(base, base, mod)
        p //= 2
    return result

