            for _ in range(s - 1):
                x_test = pow(x_test, 2, num)
                if x_test == num - 1:
                    break
            else:
                return False
        return True

    # Get divisors of n
    def get_divisors(n):
        divs = []
        i = 1
        while i * i <= n:
            if n % i == 0:
                divs.append(i)
                if i != n // i:
                    divs.append(n // i)
            i += 1
        return sorted(divs)

    # Check if b has order exactly n modulo p
    def check_order(b, p, n):
